begin;
alter table voyage_private.settings add column comments boolean not null default false;
alter table public.v26_posts drop constraint v26_posts_kind_check;
alter table public.v26_posts add column parent uuid references public.v26_posts on delete cascade,add check(kind in ('story','discussion','review','comment')),add check((kind='comment')=(parent is not null));
create index on public.v26_posts(parent,status);
create function public.v26_comment(pid uuid,content text,rights boolean) returns void language plpgsql security definer set search_path='' as $$begin if not public.v26_active() or rights is not true or not(select community and comments from voyage_private.settings) then raise exception 'Comments are closed';end if;
if not exists(select 1 from public.v26_posts f join public.v26_profiles p on p.id=f.owner where f.id=pid and f.parent is null and f.status='published' and not p.suspended and voyage_private.visible(auth.uid(),p.id)) then raise exception 'Post unavailable';end if;
perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text,0));if (select count(*) from public.v26_posts where owner=auth.uid() and created_at>now()-interval '24 hours')>=5 then raise exception 'Daily submission limit reached';end if;
insert into public.v26_posts(owner,kind,destination,title,body,parent) values(auth.uid(),'comment','','Comment',trim(content),pid);end$$;
create function public.v26_pause_comments() returns void language plpgsql security definer set search_path='' as $$begin perform public.v26_ops();update voyage_private.settings set comments=false;insert into voyage_private.audit(actor,action,subject) values(auth.uid(),'pause','comments');end$$;
create or replace function public.v26_feed(filter_kind text default '',place_name text default '',page_no int default 0) returns table(id uuid,kind text,destination text,title text,body text,scores jsonb,username text,created_at timestamptz) language sql stable security definer set search_path='' as $$select f.id,f.kind,f.destination,f.title,f.body,f.scores,p.username,f.created_at from public.v26_posts f join public.v26_profiles p on p.id=f.owner where (select community from voyage_private.settings) and not p.suspended and voyage_private.visible(auth.uid(),p.id) and f.status='published' and ((f.parent is null and (filter_kind='' or filter_kind=f.kind) and (place_name='' or lower(place_name)=lower(f.destination))) or (filter_kind='comment' and f.parent::text=place_name and exists(select 1 from public.v26_posts par join public.v26_profiles pp on pp.id=par.owner where par.id=f.parent and par.status='published' and not pp.suspended and voyage_private.visible(auth.uid(),pp.id)))) order by f.created_at desc,f.id limit 25 offset greatest(0,least(page_no,10000))*25$$;
revoke all on function public.v26_comment(uuid,text,boolean),public.v26_pause_comments() from public,anon,authenticated;
grant execute on function public.v26_comment(uuid,text,boolean),public.v26_pause_comments() to authenticated;
commit;
